import re
import os
from ta_moler.cmd.egen.genericegen import GenericEgen
from moler.exceptions import ParsingDone, CommandFailure


class Egen(GenericEgen):
    """Egen command class."""

    def __init__(self, connection, port, cores=None, send=None, sourcemac=None, capture=None, loops=None, egen_path=None,
                 prompt=None, newline_chars=None, runner=None, options=None):
        """
        Egen command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param port: egen command port -  enables both tx and rx(list of ports could be passed too).
        :param send: pcap file to send.
        :param cores: number of cores.
        :param sourcemac: sourcemac.
        :param capture: path to output pcap file.
        :param loops: loops iterations.
        :param egen_path: path to egen cmd if None default.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        :param options: Rest of available options
                        https://alatos.gitlabe1-pages.ext.net.nokia.com/eGen/master/options.html
        """
        super(Egen, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.egen_path = egen_path
        self.port = port
        self.cores = cores
        self.send = send
        self.sourcemac = sourcemac
        self.capture = capture
        self.loops = loops
        self.options = options
        self.ret_required = False
        self._first_line_time = None
        self._check_failure_indication = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "egen"

        if self.egen_path:
            cmd = os.path.join(self.egen_path, cmd)

        ports = " --port ".join(self.port) if isinstance(self.port, list) else self.port

        cmd = f"{cmd} --port {ports}"

        if self.cores:
            cmd = f"{cmd} --cores {self.cores}"
        if self.send:
            cmd = f"{cmd} --send {self.send}"
        if self.sourcemac:
            cmd = f"{cmd} --sourcemac {self.sourcemac}"
        if self.capture:
            cmd = f"{cmd} --capture {self.capture}"
        if self.loops:
            cmd = f"{cmd} --loops {self.loops}"
        if self.options:
            cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_no_such_file(line)
            except ParsingDone:
                pass
        return super(Egen, self).on_new_line(line, is_full_line)

    _re_parse_no_such_file = re.compile(r"(?P<ERROR>No such file or directory)")

    def _parse_no_such_file(self, line):
        """
        Parse invalid number in line.

        :param line: Line from device.
        :return: None.
        :raise ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Egen._re_parse_no_such_file, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))

            raise ParsingDone


